#iostream
#include <iostream>

const int INSIDE = 0; // 0000
const int LEFT = 1;   // 0001
const int RIGHT = 2;  // 0010
const int BOTTOM = 4; // 0100
const int TOP = 8;    // 1000

const double x_min = 4.0, x_max = 10.0;
const double y_min = 4.0, y_max = 10.0;

int computeCode(double x, double y) {
    int code = INSIDE;
    if (x < x_min)      code |= LEFT;
    else if (x > x_max) code |= RIGHT;
    if (y < y_min)      code |= BOTTOM;
    else if (y > y_max) code |= TOP;
    return code;
}

void cohenSutherlandClip(double x0, double y0, double x1, double y1) {
    int code0 = computeCode(x0, y0);
    int code1 = computeCode(x1, y1);
    bool accept = false;

    while (true) {
        if ((code0 | code1) == 0) {
            accept = true; break; // Trivial accept
        } else if (code0 & code1) {
            break; // Trivial reject
        } else {
            double x, y;
            int outcodeOut = code0 ? code0 : code1;

            if (outcodeOut & TOP) {
                x = x0 + (x1 - x0) * (y_max - y0) / (y1 - y0);
                y = y_max;
            } else if (outcodeOut & BOTTOM) {
                x = x0 + (x1 - x0) * (y_min - y0) / (y1 - y0);
                y = y_min;
            } else if (outcodeOut & RIGHT) {
                y = y0 + (y1 - y0) * (x_max - x0) / (x1 - x0);
                x = x_max;
            } else if (outcodeOut & LEFT) {
                y = y0 + (y1 - y0) * (x_min - x0) / (x1 - x0);
                x = x_min;
            }

            if (outcodeOut == code0) {
                x0 = x; y0 = y; code0 = computeCode(x0, y0);
            } else {
                x1 = x; y1 = y; code1 = computeCode(x1, y1);
            }
        }
    }
    if (accept)
        std::cout << "Line accepted from (" << x0 << ", " << y0 << ") to (" << x1 << ", " << y1 << ")\n";
    else
        std::cout << "Line rejected\n";
}

int main() {
    cohenSutherlandClip(5.0, 5.0, 7.0, 7.0); // Inside
    cohenSutherlandClip(1.0, 1.0, 2.0, 2.0); // Outside
    return 0;
}

