// Simple demonstration of Perspective vs Orthographic projection mapping
struct Point3D { float x, y, z; };
struct Point2D { float x, y; };

Point2D orthographicProjection(Point3D p) {
    // Discard Z, keep X and Y
    return {p.x, p.y};
}

Point2D perspectiveProjection(Point3D p, float d) {
    // Divide by depth Z scaled by distance d
    float factor = d / p.z;
    return {p.x * factor, p.y * factor};
}

int main() {
