#include <iostream>
#include <vector>

struct Vector4 { float x, y, z, w; };

// Simplified Perspective Projection Matrix calculation
void applyPerspectiveMatrix(Vector4& v, float fovRad, float aspect, float nearP, float farP) {
    float f = 1.0f / tan(fovRad / 2.0f);
    // Applying standard OpenGL-style perspective matrix transformation manually
    float X = f / aspect * v.x;
    float Y = f * v.y;
    float Z = ((farP + nearP) / (nearP - farP)) * v.z + ((2.0f * farP * nearP) / (nearP - farP));
    float W = -v.z; // W stores -z for division

    v = {X, Y, Z, W};

    // Perspective Division
    if (v.w != 0) {
        v.x /= v.w;
        v.y /= v.w;
        v.z /= v.w;
        v.w = 1.0f;
    }
}

int main() {
    Vector4 vertex = {2.0f, 3.0f, -5.0f, 1.0f};
    applyPerspectiveMatrix(vertex, 1.57f, 1.33f, 0.1f, 100.0f);
    std::cout << "NDC Coord: (" << vertex.x << ", " << vertex.y << ", " << vertex.z << ")\n";
