};

// Function to multiply 3x3 matrix with a 3x1 vector
Point3D multiplyMatrixVector(double mat[3][3], Point3D pt) {
    Point3D result;
    result.x = mat[0][0] * pt.x + mat[0][1] * pt.y + mat[0][2] * pt.w;
    result.y = mat[1][0] * pt.x + mat[1][1] * pt.y + mat[1][2] * pt.w;
    result.w = mat[2][0] * pt.x + mat[2][1] * pt.y + mat[2][2] * pt.w;
    return result;
}

