// Basic back-face culling check for a polygon
bool isBackFace(const std::vector<Point3D>& poly) {
    // Assuming CCW vertex order: compute normal via cross product of two edges
    Point3D edge1 = {poly[1].x - poly[0].x, poly[1].y - poly[0].y, poly[1].z - poly[0].z};
    Point3D edge2 = {poly[2].x - poly[1].x, poly[2].y - poly[1].y, poly[2].z - poly[1].z};

    // Z-component of cross product
    float z_normal = (edge1.x * edge2.y) - (edge1.y * edge2.x);
    return z_normal < 0; // Cull if pointing away from camera (negative Z)
}

