void warnockSubdivide(Rectangle r) {
    // Base case: 1x1 pixel region
    if (r.xMax - r.xMin <= 1 && r.yMax - r.yMin <= 1) {
        cout << "Rendering pixel at (" << r.xMin << ", " << r.yMin << ")\n";
