    // If complex, split into 4 quadrants:
    int midX = (r.xMin + r.xMax) / 2;
    int midY = (r.yMin + r.yMax) / 2;

    // Quadrant 1: Top-Left
    warnockSubdivide({r.xMin, midY, midX, r.yMax});
    // Quadrant 2: Top-Right
    warnockSubdivide({midX, midY, r.xMax, r.yMax});
    // Quadrant 3: Bottom-Left
    warnockSubdivide({r.xMin, r.yMin, midX, midY});
    // Quadrant 4: Bottom-Right
    warnockSubdivide({midX, r.yMin, r.xMax, midY});
