struct Point {
    double x, y;
};

// Cubic Bézier curve evaluation using 4 control points
Point evaluateCubicBezier(Point p0, Point p1, Point p2, Point p3, double t) {
    double u = 1.0 - t;
    double tt = t * t;
    double uu = u * u;
    double uuu = uu * u;
    double ttt = tt * t;

    Point p;
    // B(t) = (1-t)^3*P0 + 3(1-t)^2*t*P1 + 3(1-t)*t^2*P2 + t^3*P3
    p.x = uuu * p0.x + 3 * uu * t * p1.x + 3 * u * tt * p2.x + ttt * p3.x;
    p.y = uuu * p0.y + 3 * uu * t * p1.y + 3 * u * tt * p2.y + ttt * p3.y;
    return p;
}

int main() {
    Point p0 = {0, 0}, p1 = {1, 3}, p2 = {3, 3}, p3 = {4, 0};
    cout << "Cubic Bézier curve sampling (t = 0.5):\n";
    Point mid = evaluateCubicBezier(p0, p1, p2, p3, 0.5);
    cout << "Midpoint -> (x: " << mid.x << ", y: " << mid.y << ")\n";
