#include <iostream>
#include <vector>

// Simplified Cox-de Boor recursion for B-spline basis functions
double bSplineBasis(int i, int p, double u, const std::vector<double>& U) {
    if (p == 0) {
        return (U[i] <= u && u < U[i + 1]) ? 1.0 : 0.0;
    }
    double left = 0.0, right = 0.0;
    double denom1 = U[i + p] - U[i];
    if (denom1 != 0.0) {
        left = ((u - U[i]) / denom1) * bSplineBasis(i, p - 1, u, U);
    }
    double denom2 = U[i + p + 1] - U[i + 1];
    if (denom2 != 0.0) {
        right = ((U[i + p + 1] - u) / denom2) * bSplineBasis(i + 1, p - 1, u, U);
    }
    return left + right; // Combined contribution of basis functions
}

int main() {
    std::vector<double> knots = {0.0, 0.0, 0.0, 1.0, 2.0, 3.0, 3.0, 3.0};
    double u = 1.5;
    std::cout << "Basis N_{2,2}(1.5) = " << bSplineBasis(2, 2, u, knots) << std::endl;
