// Simple bilinear patch evaluation for parameters u, v in [0, 1]
Point3D evaluateBilinearPatch(const Point3D p[2][2], double u, double v) {
    Point3D result;
    // Interpol along u for bottom (v=0) and top (v=1) edges
    double x0 = (1 - u) * p[0][0].x + u * p[1][0].x;
    double y0 = (1 - u) * p[0][0].y + u * p[1][0].y;
    double z0 = (1 - u) * p[0][0].z + u * p[1][0].z;

    double x1 = (1 - u) * p[0][1].x + u * p[1][1].x;
    double y1 = (1 - u) * p[0][1].y + u * p[1][1].y;
    double z1 = (1 - u) * p[0][1].z + u * p[1][1].z;

    // Interpol along v
    result.x = (1 - v) * x0 + v * x1;
    result.y = (1 - v) * y0 + v * y1;
    result.z = (1 - v) * z0 + v * z1;
    return result;
}

