#include <iostream>
#include <cmath>

struct Vector3 { double x, y, z; };

double dot(Vector3 a, Vector3 b) {
    return a.x * b.x + a.y * b.y + a.z * b.z;
}

Vector3 normalize(Vector3 v) {
    double len = std::sqrt(dot(v, v));
    return {v.x / len, v.y / len, v.z / len};
}

// Compute Phong Illumination for a single point
double calculatePhong(Vector3 N, Vector3 L, Vector3 V, double ka, double kd, double ks, double shininess) {
    N = normalize(N);
    L = normalize(L);
    V = normalize(V);

    // Ambient term
    double ambient = ka;

    // Diffuse term (Lambert's Law)
    double ndotl = std::max(0.0, dot(N, L));
    double diffuse = kd * ndotl;

    // Specular term (Phong Reflection: R = 2(N.L)N - L)
    double specular = 0.0;
    if (ndotl > 0.0) {
        Vector3 R = {2.0 * ndotl * N.x - L.x, 2.0 * ndotl * N.y - L.y, 2.0 * ndotl * N.z - L.z};
        R = normalize(R);
        double rdotv = std::max(0.0, dot(R, V));
        specular = ks * std::pow(rdotv, shininess);
    }

    return ambient + diffuse + specular;
}

int main() {
    Vector3 N = {0.0, 0.0, 1.0}; // Pointing straight up
    Vector3 L = {0.0, 1.0, 1.0}; // Light from above-front
    Vector3 V = {0.0, 0.0, 1.0}; // Viewer looking straight down

    double intensity = calculatePhong(N, L, V, 0.1, 0.7, 0.2, 32.0);
    std::cout << "Calculated Light Intensity: " << intensity << std::endl;
    return 0;
}

