// Simulating Alpha Blending calculation for color components
struct Color { float r, g, b, a; };

Color alphaBlend(Color src, Color dst) {
    Color result;
    // src.a is the opacity of the incoming pixel
    result.r = src.a * src.r + (1.0f - src.a) * dst.r;
    result.g = src.a * src.g + (1.0f - src.a) * dst.g;
    result.b = src.a * src.b + (1.0f - src.a) * dst.b;
    result.a = src.a + dst.a * (1.0f - src.a);
